from pandas import DataFrame, Series
from numpy import zeros, asarray


class TableHeader(DataFrame):
    name2dtype = None
    name2unit = None

    def __init__(self, data=zeros([0, 4])):
        super().__init__(data=data, columns=[
            "name", "dtype", "unit", "comment"])
        self._create_name2dtype()
        self._create_name2unit()

    def _create_name2dtype(self):
        self.name2dtype = {}
        for i in range(len(self)):
            self.name2dtype[self.loc[i, "name"]] = self.loc[i, "dtype"]

    def _create_name2unit(self):
        from .units import Unit
        self.name2unit = {}
        for i in range(len(self)):
            self.name2unit[self.loc[i, "name"]] = Unit(self.loc[i, "unit"])

    @property
    def _constructor(self):
        return TableHeader

    @property
    def _constructor_sliced(self):
        return TableHeaderSeries


class TableHeaderSeries(Series):
    @property
    def _constructor(self):
        return TableHeaderSeries

    @property
    def _constructor_expanddim(self):
        return TableHeader


class DataTable(DataFrame):
    '''
    This is a class describing common variables and methods of VisTable,
    BSTable and CATable.
    '''
    header = TableHeader()

    def convert_format(self):
        columns = self.header.name.to_list()
        dtypes = self.header.dtype.to_list()

        for i in range(len(columns)):
            self[columns[i]] = asarray(
                self[columns[i]].values, dtype=dtypes[i])

    @property
    def _constructor(self):
        return DataTable

    @property
    def _constructor_sliced(self):
        return DataSeries


class DataSeries(Series):
    @property
    def _constructor(self):
        return DataSeries

    @property
    def _constructor_expanddim(self):
        return DataTable

var MongoClient = require('mongodb').MongoClient;
// Config file for DB connections

function DB() {
    this.db = null; // The MongoDB database connection variable
}

DB.prototype.connect = function (uri) {

    var _this = this;
    return new Promise(function (resolve, reject) {
        if (_this.db) {
            // Already connected
            resolve();
        } else {
            var __this = _this;
            //MongoDB driver promise
            MongoClient.connect(uri)
                .then(
                    function (database) {
                        // Store the database connection as part of the DB object
                        __this.db = database;
                        console.log('Connection is okay');
                        resolve();
                    },
                    function (err) {
                        console.log("Error connecting: " + err.message);

                        // Retrun error
                        reject(err.message);
                    }
                )
        }
    })
}

DB.prototype.close = function () {

    // Closes the database connection. 
    if (this.db) {
        console.log(this.db);
        this.db.close()
            .then(
                // Succes condition
                function () {},
                function (error) {
                    console.log("Failed to close the database: " + error.message)
                }
            )
    }
}

DB.prototype.addDocument = function (coll, document) {

    // Inserts the data comes from the client to collections

    var _this = this;

    return new Promise(function (resolve, reject) {
        _this.db.db("fb-interests").collection(coll, function (error, collection) {
            if (error) {
                console.log("Could not access collection: " + error.message);
                reject(error.message);
            } else {
                collection.insertOne(document)
                    .then(
                        function (result) {
                            resolve();
                        },
                        function (err) {
                            console.log("Insert failed: " + err.message);
                            reject(err.message);
                        }
                    )
            }
        })
    })
}

DB.prototype.findUser = function (val) {

    // Returns a document that filtered from the collection with
    // query operations

    var _this = this;

    return new Promise(function (resolve, reject) {
        _this.db.db("fb-interests").collection("user", function (error, collection) {
            if (error) {
                console.log("Could not access collection: " + error.message);
                reject(error.message);
            } else {
                console.log(val);
                var res = collection.findOne({
                    "email": val
                });

                resolve(res);

            }
        })
    })
}

DB.prototype.findCategories = function (val) {

    // Returns a document that filtered from the collection with
    // query operations

    var _this = this;

    return new Promise(function (resolve, reject) {
        _this.db.db("fb-interests").collection("categories", function (error, collection) {
            if (error) {
                console.log("Could not access collection: " + error.message);
                reject(error.message);
            } else {
                var doc = collection.findOne({
                    "email": {
                        val
                    }
                });

                resolve(doc);

            }
        })
    })
}

module.exports = DB;

